test:
from collections import Counter
schedule = build_schedule(['q1', 'q2'], ['m1', 'm2'], ['h1', 'h2'], 2)
assert len(schedule) == 4
assert Counter(h for _, _, h in schedule) == Counter({'h1': 2, 'h2': 2})
assert len({(task, human) for task, _, human in schedule}) == len(schedule)
for task, model, human in schedule:
    assert task in {'q1', 'q2'}
    assert model in {'m1', 'm2'}
    assert human in {'h1', 'h2'}

assert build_schedule(['q'], ['m'], ['h'], 0) == []
try:
    build_schedule(['q'], ['m'], ['h'], 2)
    assert False, 'expected ValueError'
except ValueError:
    pass
